-- DIBUAT OTOMATIS oleh scripts/gen-katalog-sql.ts — jangan diedit manual.
-- Katalog per daerah + kerangka bagian (draf, wajib ditinjau maestro).

on conflict (id) do update set name = excluded.name, province = excluded.province, kain = excluded.kain, sort = excluded.sort;

on conflict (id) do update set name = excluded.name, region = excluded.region, province = excluded.province, summary = excluded.summary, posture = excluded.posture, accompaniment = excluded.accompaniment, verified_by_note = excluded.verified_by_note, region_id = excluded.region_id, difficulty = excluded.difficulty;

on conflict (dance_id, kind) do update set label = excluded.label, note = excluded.note;

on conflict (dance_id, order_index) do update set name = excluded.name, focus = excluded.focus, counts = excluded.counts;

-- Gerak acuan dari rekaman bawaan aplikasi (video, lagu, dan kerangka di public/).
on conflict (id) do update set name = excluded.name, description = excluded.description, counts = excluded.counts, duration_ms = excluded.duration_ms, aspect = excluded.aspect, prop = excluded.prop, keypoints_path = excluded.keypoints_path, video_path = excluded.video_path, audio_path = excluded.audio_path, recorded_by_label = excluded.recorded_by_label, status = excluded.status, part_id = excluded.part_id;

